+class ContactViewBrowserIT {
+
+    @LocalServerPort
+    int port;
+
+    Playwright playwright;
+    Browser browser;
+    Page page;
+
+    @BeforeEach
+    void open() {
+        playwright = Playwright.create();
+        browser = playwright.chromium().launch();
+        page = browser.newPage();
+        page.setDefaultTimeout(20000);
+        page.navigate("http://localhost:" + port + "/contact");
+        page.waitForSelector("vaadin-text-field");
+    }
+
+    @AfterEach
+    void close() {
+        playwright.close();
+    }
+
+    Locator field(String tag, String label) {
+        return page.locator(tag).filter(new Locator.FilterOptions().setHas(
+                page.locator("label", new Page.LocatorOptions().setHasText(label)))).locator("input, textarea");
+    }
+
+    @Test
+    void validateSendAndLeave() {
+        Locator send = page.getByRole(AriaRole.BUTTON, new Page.GetByRoleOptions().setName("Send"));
+        send.click();
+        assertThat(page.getByText("Name is required")).isVisible();
+        assertThat(page.getByText("Give an e-mail address or a phone number")).isVisible();
+        assertThat(page.getByText("Message is required")).isVisible();
+
+        field("vaadin-text-field", "Name").fill("Browser Bob");
+        field("vaadin-email-field", "Email").fill("bad");
+        field("vaadin-text-area", "Message").fill("Hi from browser");
+        send.click();
+        assertThat(page.getByText("Enter a valid e-mail address")).isVisible();
+
+        field("vaadin-email-field", "Email").fill("bob@example.com");
+        field("vaadin-email-field", "Email").press("Enter");
+        assertThat(page.locator("vaadin-notification-card")).containsText("Message sent");
+        assertThat(page.locator("vaadin-grid")).containsText("Browser Bob");
+        assertThat(field("vaadin-text-field", "Name")).hasValue("");
+        assertThat(send).isDisabled();
+        field("vaadin-text-field", "Phone").fill("1");
+        assertThat(send).isEnabled();
+
+        page.getByText("About").click();
+        Locator keep = page.getByRole(AriaRole.BUTTON, new Page.GetByRoleOptions().setName("Keep editing"));
+        assertThat(keep).isVisible();
+        keep.click();
+        assertThat(keep).isHidden();
+        assertThat(field("vaadin-text-field", "Phone")).hasValue("1");
+
+        page.getByText("About").click();
+        page.getByRole(AriaRole.BUTTON, new Page.GetByRoleOptions().setName("Discard")).click();
+        assertThat(page.locator("h1")).hasText("About");
+
+        page.goBack();
+        assertThat(page.locator("h1")).hasText("Contact");
+        assertThat(page.locator("vaadin-grid")).containsText("Browser Bob");
+        page.getByText("About").click();
+        assertThat(page.locator("h1")).hasText("About");
+    }
+}
